INSERT INTO public.articulos (id, ley_id, orden, identificador, contenido, tipo_articulo, titulo_nombre, capitulo_nombre, seccion_nombre) VALUES ('63cf32d2-e33b-5120-bfa0-265c33ba779d', '739c6ab8-ab67-5aa8-9ed3-83905deec56a', '1', 'Convocatoria · CFE-0001-CAAAT-0096-2026', '<p>COMISION FEDERAL DE ELECTRICIDAD Con fundamento en el Artículo 134 de la Constitución Política de los Estados Unidos Mexicanos, Artículos 80 y 82 la Ley de la Empresa Pública del Estado, Comisión Federal de Electricidad, en las disposiciones 2 fracción I, 30 fracción I inciso b), 31, 33 fracciones I,III, IV, VI y VII, 34, 37 fracción I, 52 y 55 fracciones III y IV de las Disposiciones Generales en Materia de adquisiciones, arrendamientos, contratación de servicios y ejecución de obras de la Comisión Federal de Electricidad y sus Empresas Productivas Subsidiarias (en lo sucesivo Disposiciones), de conformidad con lo siguiente:</p>
